Política de contraseñas.ejemplo:
# Verificación k-anonymity contra Have I Been Pwned (solo envía los 5 primeros caracteres del SHA-1)
HASH=$(printf '%s' "MiFraseDePasoSegura" | sha1sum | awk '{print toupper($1)}')
PREFIX=${HASH:0:5}
SUFFIX=${HASH:5}
curl -s "https://api.pwnedpasswords.com/range/${PREFIX}" | grep -i "${SUFFIX}"

