Session fixation.ejemplo:
// Regeneración obligatoria de sesión tras login exitoso (Express)
app.post("/login", async (req, res) => {
  const user = await authenticate(req.body.email, req.body.password);
  if (!user) return res.status(401).end();
  req.session.regenerate((err) => {
    req.session.userId = user.id;
    res.redirect("/dashboard");
  });
});

Session management.ejemplo:
// Validación de sesión con idle y absolute timeout en servidor
const now = Date.now();
if (!session || now > session.absoluteExpiresAt || now - session.lastSeenAt > IDLE_TTL) {
  await sessionStore.destroy(sessionId);
  return res.status(401).json({ error: "session_expired" });
}
session.lastSeenAt = now;

scrypt.ejemplo:
const crypto = require("crypto");
const salt = crypto.randomBytes(16);
// N=32768, r=8, p=1 (~32 MiB de memoria por derivación)
crypto.scrypt("MiClaveSegura", salt, 64, { N: 32768, r: 8, p: 1, maxmem: 64 * 1024 * 1024 }, (err, key) => {
  if (err) throw err;
  console.log(`${salt.toString("hex")}:${key.toString("hex")}`);
});
